/**
 * Minimal, dependency-free JUnit XML parser scoped to exactly the shape
 * vitest's built-in "junit" reporter emits (see packages/config/vitest/base.js).
 * Not a general-purpose XML parser — a hand-rolled tag scan is enough
 * because the input is always machine-generated by vitest, never
 * user-authored XML.
 *
 * Output shape matches computeFlakyTests' expected input rows (minus `sha`,
 * which the caller attaches from the CI run the XML came from):
 *   Array<{ testName: string, passed: boolean }>
 */

const TESTCASE_RE = /<testcase\b([^>]*?)(?:\/>|>([\s\S]*?)<\/testcase>)/g;
const ATTR_RE = /(\w+)="([^"]*)"/g;

/** Decodes the small set of XML entities vitest's junit reporter emits. */
function decodeXmlEntities(value) {
  return value
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_match, code) => String.fromCodePoint(Number(code)))
    .replace(/&amp;/g, "&");
}

function parseAttrs(attrString) {
  const attrs = {};
  ATTR_RE.lastIndex = 0;
  let match;
  while ((match = ATTR_RE.exec(attrString))) {
    attrs[match[1]] = decodeXmlEntities(match[2]);
  }
  return attrs;
}

/**
 * @param {string | null | undefined} xml
 * @returns {Array<{ testName: string, passed: boolean }>}
 */
export function parseJUnitXml(xml) {
  if (!xml || !xml.trim()) return [];

  const results = [];
  TESTCASE_RE.lastIndex = 0;
  let match;
  while ((match = TESTCASE_RE.exec(xml))) {
    const [, attrString, body = ""] = match;
    const attrs = parseAttrs(attrString);

    // Skipped tests didn't actually run — no pass/fail signal to record.
    if (/<skipped\b/.test(body)) continue;

    const passed = !/<failure\b|<error\b/.test(body);
    const testName = `${attrs.classname ?? ""} > ${attrs.name ?? ""}`;
    results.push({ testName, passed });
  }
  return results;
}
